package com.sumedha.commerce.product.entity; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="product_images") public class ProductImage{@Id @Column(name="image_id") private UUID id;@Column(name="product_id") private UUID productId;private String url;@Column(name="alt_text") private String altText;@Column(name="sort_order") private int sortOrder;@Column(name="primary_image") private boolean primaryImage;@Column(name="created_at") private Instant createdAt;protected ProductImage(){}public ProductImage(UUID p,String u,String a,int s,boolean primary){id=UUID.randomUUID();productId=p;url=u;altText=a;sortOrder=s;primaryImage=primary;createdAt=Instant.now();}public UUID getId(){return id;}public UUID getProductId(){return productId;}public String getUrl(){return url;}public String getAltText(){return altText;}public int getSortOrder(){return sortOrder;}public boolean isPrimaryImage(){return primaryImage;}public Instant getCreatedAt(){return createdAt;}public void update(String u,String a,int s,boolean primary){url=u;altText=a;sortOrder=s;primaryImage=primary;}public void setPrimaryImage(boolean primary){primaryImage=primary;}}
